#include <furi.h>
#include <furi_hal_subghz.h>
#include <furi_hal_vibro.h>
#include <furi_hal_rtc.h>
#include <gui/gui.h>
#include <input/input.h>
#include <lib/subghz/devices/cc1101_configs.h>
#include <storage/storage.h>

#include "bleepsentry_logic.h"

/* generated by fbt from .png files in images folder */
#include <bleepsentry_icons.h>

#define LOG_FILE_PATH APP_DATA_PATH("log.csv")

#define TAG "Bleepsentry"

#define RSSI_POLL_PERIOD_MS 100
#define BASELINE_SAMPLE_MS  2000
#define ALERT_MARGIN_DB     12.0f
#define RSSI_MIN_DBM        -100.0f
#define RSSI_MAX_DBM        0.0f

typedef enum {
    BsEventTypeTick,
    BsEventTypeInput,
} BsEventType;

typedef struct {
    BsEventType type;
    InputEvent input;
} BsEvent;

typedef enum {
    BsModeIdle,
    BsModeScanning,
    BsModeCalibrating,
    BsModeSweepCalibrating,
    BsModeSweeping,
} BsMode;

#define SWEEP_DWELL_MS (BASELINE_SAMPLE_MS / 2)

static const uint32_t frequencies[] = {
    300000000,
    433920000,
    868350000,
    915000000,
};
#define FREQ_COUNT (sizeof(frequencies) / sizeof(frequencies[0]))

typedef struct {
    FuriMutex* mutex;
    FuriMessageQueue* queue;
    FuriTimer* timer;

    size_t freq_index;
    float rssi;
    float baseline;
    float threshold;
    bool has_baseline;
    bool alerting;
    BsMode mode;

    uint32_t calib_ticks_left;
    float calib_sum;
    uint32_t calib_count;

    float baselines[FREQ_COUNT];
    float thresholds[FREQ_COUNT];
    bool has_baseline_arr[FREQ_COUNT];
    uint32_t sweep_dwell_ticks_left;

    Storage* storage;
    File* log_file;
    uint32_t alert_start_timestamp;
    float alert_peak_rssi;
    uint32_t events_logged;

    bool pending_vibro_pulse;
} BsApp;

static uint32_t bs_now(void) {
    DateTime dt;
    furi_hal_rtc_get_datetime(&dt);
    return datetime_datetime_to_timestamp(&dt);
}

static void bs_log_open(BsApp* app) {
    app->storage = furi_record_open(RECORD_STORAGE);
    storage_common_mkdir(app->storage, STORAGE_APP_DATA_PATH_PREFIX);
    app->log_file = storage_file_alloc(app->storage);
    bool exists = storage_file_exists(app->storage, LOG_FILE_PATH);
    if(storage_file_open(app->log_file, LOG_FILE_PATH, FSAM_WRITE, FSOM_OPEN_APPEND)) {
        if(!exists) {
            const char* header =
                "timestamp,freq_hz,baseline_dbm,threshold_dbm,peak_rssi_dbm,duration_s\n";
            storage_file_write(app->log_file, header, strlen(header));
        }
    }
}

static void bs_log_event(BsApp* app, uint32_t duration_s) {
    if(!storage_file_is_open(app->log_file)) return;
    char line[128];
    int len = bs_format_log_line(
        line,
        sizeof(line),
        app->alert_start_timestamp,
        frequencies[app->freq_index],
        (int)app->baseline,
        (int)app->threshold,
        (int)app->alert_peak_rssi,
        duration_s);
    storage_file_write(app->log_file, line, len);
    app->events_logged++;
}

static void bs_log_close(BsApp* app) {
    if(app->log_file) {
        storage_file_close(app->log_file);
        storage_file_free(app->log_file);
    }
    if(app->storage) furi_record_close(RECORD_STORAGE);
}

static void bs_radio_start(BsApp* app) {
    furi_hal_subghz_reset();
    furi_hal_subghz_idle();
    furi_hal_subghz_load_custom_preset(subghz_device_cc1101_preset_ook_650khz_async_regs);
    furi_hal_subghz_set_frequency_and_path(frequencies[app->freq_index]);
    furi_hal_subghz_flush_rx();
    furi_hal_subghz_rx();
}

static void bs_radio_stop(void) {
    furi_hal_subghz_idle();
    furi_hal_subghz_sleep();
}

static void bs_timer_callback(void* context) {
    BsApp* app = context;
    BsEvent event = {.type = BsEventTypeTick};
    furi_message_queue_put(app->queue, &event, 0);
}

static void bs_input_callback(InputEvent* input_event, void* context) {
    BsApp* app = context;
    BsEvent event = {.type = BsEventTypeInput, .input = *input_event};
    furi_message_queue_put(app->queue, &event, 0);
}

static void bs_draw_callback(Canvas* canvas, void* context) {
    BsApp* app = context;
    furi_mutex_acquire(app->mutex, FuriWaitForever);

    canvas_clear(canvas);
    canvas_set_font(canvas, FontPrimary);
    canvas_draw_str(canvas, 2, 10, "Bleepsentry");

    canvas_set_font(canvas, FontSecondary);
    char buf[48];
    snprintf(
        buf,
        sizeof(buf),
        "%lu.%02lu MHz",
        frequencies[app->freq_index] / 1000000,
        (frequencies[app->freq_index] / 10000) % 100);
    canvas_draw_str(canvas, 2, 22, buf);

    snprintf(buf, sizeof(buf), "RSSI: %d dBm", (int)app->rssi);
    canvas_draw_str(canvas, 2, 33, buf);

    if(app->has_baseline) {
        snprintf(buf, sizeof(buf), "Base: %d  Thr: %d", (int)app->baseline, (int)app->threshold);
        canvas_draw_str(canvas, 2, 43, buf);
    } else {
        canvas_draw_str(canvas, 2, 43, "No baseline (press OK)");
    }

    /* RSSI bar */
    int32_t bar_x = 2, bar_y = 48, bar_w = 120, bar_h = 8;
    canvas_draw_frame(canvas, bar_x, bar_y, bar_w, bar_h);
    float frac = (app->rssi - RSSI_MIN_DBM) / (RSSI_MAX_DBM - RSSI_MIN_DBM);
    if(frac < 0) frac = 0;
    if(frac > 1) frac = 1;
    int32_t fill_w = (int32_t)(frac * (bar_w - 2));
    if(fill_w > 0) canvas_draw_box(canvas, bar_x + 1, bar_y + 1, fill_w, bar_h - 2);

    if(app->mode == BsModeCalibrating) {
        canvas_draw_str(canvas, 2, 63, "Calibrating baseline...");
    } else if(app->mode == BsModeSweepCalibrating) {
        snprintf(buf, sizeof(buf), "Sweep calib %u/%u", (unsigned)app->freq_index + 1, FREQ_COUNT);
        canvas_draw_str(canvas, 2, 63, buf);
    } else if(app->alerting) {
        canvas_set_font(canvas, FontPrimary);
        canvas_draw_str(canvas, 70, 63, "ALERT");
    } else if(app->mode == BsModeSweeping) {
        snprintf(buf, sizeof(buf), "Sweeping  Log:%lu", (unsigned long)app->events_logged);
        canvas_draw_str(canvas, 2, 63, buf);
    } else {
        snprintf(buf, sizeof(buf), "Logged: %lu", (unsigned long)app->events_logged);
        canvas_draw_str(canvas, 2, 63, buf);
    }

    furi_mutex_release(app->mutex);
}

static void bs_start_calibration(BsApp* app) {
    app->mode = BsModeCalibrating;
    app->calib_ticks_left = BASELINE_SAMPLE_MS / RSSI_POLL_PERIOD_MS;
    app->calib_sum = 0;
    app->calib_count = 0;
}

/* Close out an in-progress alert (used when leaving a frequency mid-alert
 * during a sweep, so the event still gets logged with a real duration). */
static void bs_close_alert_if_active(BsApp* app) {
    if(app->alerting) {
        bs_log_event(app, bs_alert_duration(app->alert_start_timestamp, bs_now()));
        app->alerting = false;
    }
}

static void bs_sync_scalars_from_array(BsApp* app) {
    app->baseline = app->baselines[app->freq_index];
    app->threshold = app->thresholds[app->freq_index];
    app->has_baseline = app->has_baseline_arr[app->freq_index];
}

static void bs_start_sweep_calibration(BsApp* app) {
    bs_close_alert_if_active(app);
    for(size_t i = 0; i < FREQ_COUNT; i++)
        app->has_baseline_arr[i] = false;
    app->freq_index = 0;
    app->has_baseline = false; /* avoid showing a stale baseline/threshold
                                   from a previous manual calibration while
                                   the sweep calibration is in progress */
    bs_radio_start(app);
    app->mode = BsModeSweepCalibrating;
    app->calib_ticks_left = BASELINE_SAMPLE_MS / RSSI_POLL_PERIOD_MS;
    app->calib_sum = 0;
    app->calib_count = 0;
}

static void bs_sweep_advance(BsApp* app) {
    bs_close_alert_if_active(app);
    app->freq_index = bs_next_index(app->freq_index, FREQ_COUNT);
    bs_radio_start(app);
    bs_sync_scalars_from_array(app);
    app->sweep_dwell_ticks_left = SWEEP_DWELL_MS / RSSI_POLL_PERIOD_MS;
}

int32_t bleepsentry_app(void* p) {
    UNUSED(p);

    BsApp* app = malloc(sizeof(BsApp));
    app->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    app->queue = furi_message_queue_alloc(8, sizeof(BsEvent));
    app->freq_index = 1; /* 433.92 MHz default */
    app->rssi = RSSI_MIN_DBM;
    app->baseline = RSSI_MIN_DBM;
    app->threshold = RSSI_MIN_DBM;
    app->has_baseline = false;
    app->alerting = false;
    app->mode = BsModeIdle;
    app->events_logged = 0;
    for(size_t i = 0; i < FREQ_COUNT; i++) {
        app->baselines[i] = RSSI_MIN_DBM;
        app->thresholds[i] = RSSI_MIN_DBM;
        app->has_baseline_arr[i] = false;
    }
    app->sweep_dwell_ticks_left = 0;
    app->pending_vibro_pulse = false;

    bs_log_open(app);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, bs_draw_callback, app);
    view_port_input_callback_set(view_port, bs_input_callback, app);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    bs_radio_start(app);
    app->mode = BsModeScanning;

    app->timer = furi_timer_alloc(bs_timer_callback, FuriTimerTypePeriodic, app);
    furi_timer_start(app->timer, furi_ms_to_ticks(RSSI_POLL_PERIOD_MS));

    bool running = true;
    BsEvent event;
    while(running) {
        if(furi_message_queue_get(app->queue, &event, FuriWaitForever) == FuriStatusOk) {
            furi_mutex_acquire(app->mutex, FuriWaitForever);

            if(event.type == BsEventTypeTick) {
                float rssi = furi_hal_subghz_get_rssi();
                app->rssi = rssi;

                if(app->mode == BsModeCalibrating) {
                    app->calib_sum += rssi;
                    app->calib_count++;
                    if(app->calib_ticks_left > 0) app->calib_ticks_left--;
                    if(app->calib_ticks_left == 0) {
                        app->baseline = app->calib_count ? (app->calib_sum / app->calib_count) :
                                                           RSSI_MIN_DBM;
                        app->threshold = bs_compute_threshold(app->baseline, ALERT_MARGIN_DB);
                        app->has_baseline = true;
                        app->baselines[app->freq_index] = app->baseline;
                        app->thresholds[app->freq_index] = app->threshold;
                        app->has_baseline_arr[app->freq_index] = true;
                        app->mode = BsModeScanning;
                    }
                } else if(app->mode == BsModeSweepCalibrating) {
                    app->calib_sum += rssi;
                    app->calib_count++;
                    if(app->calib_ticks_left > 0) app->calib_ticks_left--;
                    if(app->calib_ticks_left == 0) {
                        float base = app->calib_count ? (app->calib_sum / app->calib_count) :
                                                        RSSI_MIN_DBM;
                        app->baselines[app->freq_index] = base;
                        app->thresholds[app->freq_index] =
                            bs_compute_threshold(base, ALERT_MARGIN_DB);
                        app->has_baseline_arr[app->freq_index] = true;

                        if(app->freq_index + 1 < FREQ_COUNT) {
                            app->freq_index++;
                            bs_radio_start(app);
                            app->calib_ticks_left = BASELINE_SAMPLE_MS / RSSI_POLL_PERIOD_MS;
                            app->calib_sum = 0;
                            app->calib_count = 0;
                        } else {
                            app->freq_index = 0;
                            bs_radio_start(app);
                            bs_sync_scalars_from_array(app);
                            app->sweep_dwell_ticks_left = SWEEP_DWELL_MS / RSSI_POLL_PERIOD_MS;
                            app->mode = BsModeSweeping;
                        }
                    }
                } else if(
                    (app->mode == BsModeScanning || app->mode == BsModeSweeping) &&
                    app->has_baseline) {
                    bool was_alerting = app->alerting;
                    app->alerting = bs_should_alert(rssi, app->threshold);
                    if(app->alerting && !was_alerting) {
                        app->alert_start_timestamp = bs_now();
                        app->alert_peak_rssi = rssi;
                        app->pending_vibro_pulse = true;
                    } else if(app->alerting) {
                        if(rssi > app->alert_peak_rssi) app->alert_peak_rssi = rssi;
                    } else if(!app->alerting && was_alerting) {
                        bs_log_event(app, bs_alert_duration(app->alert_start_timestamp, bs_now()));
                    }

                    if(app->mode == BsModeSweeping) {
                        if(app->sweep_dwell_ticks_left > 0) app->sweep_dwell_ticks_left--;
                        if(app->sweep_dwell_ticks_left == 0) bs_sweep_advance(app);
                    }
                }
            } else if(event.type == BsEventTypeInput) {
                InputEvent* input = &event.input;
                if(input->key == InputKeyBack && input->type == InputTypeShort) {
                    running = false;
                } else if(input->key == InputKeyOk && input->type == InputTypeLong) {
                    bs_start_sweep_calibration(app);
                } else if(input->key == InputKeyOk && input->type == InputTypeShort) {
                    bs_start_calibration(app);
                } else if(
                    (input->type == InputTypeShort || input->type == InputTypeRepeat) &&
                    (input->key == InputKeyUp || input->key == InputKeyRight ||
                     input->key == InputKeyDown || input->key == InputKeyLeft)) {
                    bs_close_alert_if_active(app);
                    if(input->key == InputKeyUp || input->key == InputKeyRight) {
                        app->freq_index = bs_next_index(app->freq_index, FREQ_COUNT);
                    } else {
                        app->freq_index = bs_prev_index(app->freq_index, FREQ_COUNT);
                    }
                    app->mode = BsModeScanning;
                    bs_sync_scalars_from_array(app);
                    app->alerting = false;
                    bs_radio_start(app);
                }
            }

            bool do_vibro = app->pending_vibro_pulse;
            app->pending_vibro_pulse = false;

            furi_mutex_release(app->mutex);
            view_port_update(view_port);

            /* Done outside the mutex so a 50ms vibro pulse never stalls the
             * GUI thread's draw callback, which also waits on this mutex. */
            if(do_vibro) {
                furi_hal_vibro_on(true);
                furi_delay_ms(50);
                furi_hal_vibro_on(false);
            }
        }
    }

    furi_timer_stop(app->timer);
    furi_timer_free(app->timer);

    bs_radio_stop();
    bs_close_alert_if_active(app);
    bs_log_close(app);

    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);

    furi_message_queue_free(app->queue);
    furi_mutex_free(app->mutex);
    free(app);

    return 0;
}
